class OperatorDomain:
    query: pinnjax.SpatialDomain
    descriptor: pinnjax.Domain

    def combined_domain(self, descriptor_count: int | None = None) -&gt; pinnjax.Domain:
        query_min = tuple(self.query.min)
        query_max = tuple(self.query.max)

        query_axis_names = tuple(getattr(self.query, "axis_names", ()) or ())

        if self.query.times is not None:
            query_min = query_min + (self.query.times.min,)
            query_max = query_max + (self.query.times.max,)
            query_axis_names = query_axis_names + ("t",)

        if descriptor_count is None:
            descriptor_min = tuple(self.descriptor.min)
            descriptor_max = tuple(self.descriptor.max)
            descriptor_axis_names = tuple(
                getattr(self.descriptor, "axis_names", ()) or ()
            )
        else:
            if descriptor_count &lt; 1:
                raise ValueError("descriptor_count must be &gt;= 1.")

            if len(self.descriptor.min) != 1 or len(self.descriptor.max) != 1:
                raise ValueError(
                    "combined_domain(descriptor_count=...) currently assumes "
                    "a 1D descriptor domain whose bounds can be repeated."
                )

            dmin = self.descriptor.min[0]
            dmax = self.descriptor.max[0]

            base_name = None
            if getattr(self.descriptor, "axis_names", None):
                if len(self.descriptor.axis_names) &gt; 0:
                    base_name = self.descriptor.axis_names[0]

            descriptor_min = tuple([dmin] * descriptor_count)
            descriptor_max = tuple([dmax] * descriptor_count)

            if base_name is None:
                descriptor_axis_names = tuple(
                    f"descriptor_{i}" for i in range(descriptor_count)
                )
            else:
                descriptor_axis_names = tuple(
                    f"{base_name}_{i}" for i in range(descriptor_count)
                )

        axis_names = query_axis_names + descriptor_axis_names
        if len(axis_names) == 0:
            axis_names = None

        return pinnjax.Domain(
            min=query_min + descriptor_min,
            max=query_max + descriptor_max,
            axis_names=axis_names,
        )
